const express = require('express');
const Stripe = require('stripe');

const app = express();
app.use(express.json());
const stripe = new Stripe(process.env.STRIPE_PLATFORM_SECRET_KEY);

app.post('/api/marketplace/payouts/create', async (req, res) => {
  const { stripeAccountId, amount, currency } = req.body;

  if (!stripeAccountId || !amount) {
    return res.status(400).json({ error: 'Missing payout parameters' });
  }

  // Executes Stripe Connect payout directly using client-supplied stripeAccountId
  try {
    const payout = await stripe.payouts.create(
      {
        amount: Math.round(amount * 100),
        currency: currency || 'usd',
        statement_descriptor: 'Marketplace Payout'
      },
      {
        stripeAccount: stripeAccountId
      }
    );

    return res.json({ status: 'Payout initiated', payoutId: payout.id });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

module.exports = app;

corrected_code:
const express = require('express');
const Stripe = require('stripe');
const db = require('../db');

const app = express();
app.use(express.json());
const stripe = new Stripe(process.env.STRIPE_PLATFORM_SECRET_KEY);

app.post('/api/marketplace/payouts/create', async (req, res) => {
  const { amount, currency } = req.body;

  if (!amount) {
    return res.status(400).json({ error: 'Missing payout parameters' });
  }

  // Resolve connected account ID strictly from authenticated merchant profile
  const merchant = await db('platform_merchants').where({ user_id: req.user.id }).first();
  if (!merchant || !merchant.stripe_account_id) {
    return res.status(404).json({ error: 'Connected merchant account not found' });
  }

  try {
    const payout = await stripe.payouts.create(
      {
        amount: Math.round(amount * 100),
        currency: currency || 'usd',
        statement_descriptor: 'Marketplace Payout'
      },
      {
        stripeAccount: merchant.stripe_account_id
      }
    );

    return res.json({ status: 'Payout initiated', payoutId: payout.id });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

module.exports = app;
